package vn.smartfarm.iot.control;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.sql.Timestamp;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.control.pump-fencing-enabled=false"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class PumpCircuitHistoryTest {
 @Autowired PumpService pump;@Autowired PumpCircuitHistory history;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 UUID boot;Instant base,from,to;PumpCircuitRoute route=new PumpCircuitRoute("HR1",1,"HRZONE1",1,"IRRIGATION68","VALVE68");List<UUID> commands=new ArrayList<>();
 @BeforeEach void setup(){jdbc.update("DELETE FROM pump_status");jdbc.update("DELETE FROM pump_circuit_history WHERE circuit_id IN ('HR1','HR2')");boot=UUID.randomUUID();base=Instant.now().minusSeconds(2).truncatedTo(java.time.temporal.ChronoUnit.MICROS);from=base.minusSeconds(10);to=base.plusSeconds(10);commands.clear();}
 @AfterEach void cleanup(){jdbc.update("DELETE FROM pump_status");jdbc.update("DELETE FROM pump_circuit_history WHERE circuit_id IN ('HR1','HR2')");for(var id:commands)jdbc.update("DELETE FROM pump_command WHERE command_id=?",id);}
 ObjectNode packet(int seq){var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",boot.toString()).put("sequence",seq).put("timestamp",base.plusMillis(seq).toString()).put("connection","ONLINE").put("reportedState","OFF").put("safetyLockout",false).put("stateReason","BOOT");p.putObject("commandFence").put("version",1).put("lastOrdinal",0).put("restartRequired",false);var proof=p.putObject("valveInterlock").put("version",1).put("enabled",true).put("dataSource","SIMULATOR").put("state","OPEN").putNull("fault");proof.set("route",mapper.valueToTree(route));return p;}
 void receive(ObjectNode p)throws Exception{pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(p));}
 PumpCircuitHistory.Page page(){return history.list(from,to,"HR1","ALL",50,null);}
 UUID command(String action,PumpCircuitRoute r){var id=UUID.randomUUID();commands.add(id);jdbc.update("INSERT INTO pump_command(command_id,action,duration_seconds,issued_at,expires_at,state,fence_ordinal,target_boot_id,circuit_route) VALUES(?,?,?,?,?,'SENT',nextval('pump_fence_ordinal_seq'),?,?::jsonb)",id,action,action.equals("ON")?5:null,Timestamp.from(base.minusSeconds(1)),Timestamp.from(base.plusSeconds(9)),boot,r==null?null:mapper.valueToTree(r).toString());return id;}
 long ordinal(UUID id){return jdbc.queryForObject("SELECT fence_ordinal FROM pump_command WHERE command_id=?",Long.class,id);}
 @Test void unboundLegacyDoesNotInventRouteHistory()throws Exception{var p=packet(0);p.remove("valveInterlock");receive(p);assertTrue(page().items().isEmpty());}
 @Test void acceptedStatusKeepsOriginalClocksAndDuplicateOrOldStatusDoesNotAppend()throws Exception{receive(packet(2));var first=page().items().getFirst();receive(packet(2));receive(packet(1));assertEquals(List.of(first),page().items());assertEquals(base.plusMillis(2),first.observedAt());assertEquals(route,first.route());assertNull(first.commandId());}
 @Test void rejectedRouteChangeAndMalformedPacketDoNotAppend()throws Exception{receive(packet(0));var p=packet(1);((ObjectNode)p.path("valveInterlock").path("route")).put("circuitRevision",2);receive(p);assertEquals(1,page().items().size());p=packet(2);p.put("reportedState","ON");var bad=p;assertThrows(IllegalArgumentException.class,()->receive(bad));assertEquals(1,page().items().size());}
 @Test void newBootMayDeclareNewRouteButPriorHistoryRetainsOldRevision()throws Exception{receive(packet(0));var old=page().items().getFirst();boot=UUID.randomUUID();route=new PumpCircuitRoute("HR1",2,"HRZONE1",2,"IRRIGATION68","VALVE68");receive(packet(1));var rows=page().items();assertEquals(2,rows.size());assertEquals(2,rows.getFirst().route().circuitRevision());assertEquals(old,rows.getLast());}
 @Test void ackUpdatesCommandButNeverCreatesAStatusSample()throws Exception{var id=command("ON",route);var p=packet(1).put("commandId",id.toString()).put("reportedState","ON").put("stage","EXECUTED").put("status","SUCCESS");p.remove(List.of("connection","valveInterlock","stateReason"));p.putObject("commandFence").put("version",1).put("ordinal",ordinal(id));pump.receive("smartfarm/FARM001/PUMP01/ack",mapper.writeValueAsBytes(p));assertTrue(page().items().isEmpty());assertEquals("EXECUTED",history.commands(from,to,"HR1",50).items().getFirst().state());}
 @Test void knownBoundCommandIsLinkedWithoutAssumingTimerMeansOff()throws Exception{var id=command("ON",route);var p=packet(1).put("reportedState","ON").put("stateReason","COMMAND_ON");((ObjectNode)p.path("commandFence")).put("lastOrdinal",ordinal(id));receive(p);var s=page().items().getFirst();assertEquals(id,s.commandId());assertEquals("ON",s.reportedState());jdbc.update("UPDATE pump_command SET expires_at=issued_at+INTERVAL '1 second' WHERE command_id=?",id);assertEquals("ON",page().items().getFirst().reportedState());}
 @Test void routeFreeEmergencyOffIsLinkedOnlyWhenDeviceReportsItsOrdinal()throws Exception{var off=command("OFF",null);assertTrue(history.commands(from,to,"HR1",50).items().isEmpty());var p=packet(1).put("stateReason","COMMAND_OFF");((ObjectNode)p.path("commandFence")).put("lastOrdinal",ordinal(off));receive(p);assertEquals(off,page().items().getFirst().commandId());assertEquals(route,page().items().getFirst().route());}
 @Test void unknownOrdinalCannotEnterHistory()throws Exception{var p=packet(0);((ObjectNode)p.path("commandFence")).put("lastOrdinal",9007199254740991L);assertThrows(IllegalArgumentException.class,()->receive(p));assertTrue(page().items().isEmpty());}
 @Test void laterRowUpdatesCannotRewriteAnAcceptedHistoricalSample()throws Exception{receive(packet(0));var s=page().items().getFirst();jdbc.update("UPDATE pump_status SET received_at=CURRENT_TIMESTAMP,valve_interlock=jsonb_set(valve_interlock,'{state}','\"CLOSED\"')");assertEquals(List.of(s),page().items());}
 @Test void filterOnOffLockedAndCircuitDoesNotMergeBranches()throws Exception{receive(packet(0));var fault=packet(1).put("safetyLockout",true).put("stateReason","VALVE_PROOF_LOST");((ObjectNode)fault.path("valveInterlock")).put("fault","VALVE_PROOF_LOST");receive(fault);assertEquals(1,history.list(from,to,"HR1","LOCKED",50,null).items().size());assertTrue(history.list(from,to,"HR1","ON",50,null).items().isEmpty());assertEquals(2,history.list(from,to,"HR1","OFF",50,null).items().size());assertTrue(history.list(from,to,"HR2","ALL",50,null).items().isEmpty());}
 @Test void stableCursorExcludesLaterSamplesAndRejectsChangedScope()throws Exception{receive(packet(0));receive(packet(1));receive(packet(2));var a=history.list(from,to,"HR1","ALL",1,null);assertNotNull(a.nextCursor());receive(packet(3));var b=history.list(from,to,"HR1","ALL",2,a.nextCursor());assertEquals(a.ceilingId(),b.ceilingId());assertEquals(2,b.items().size());assertTrue(b.items().stream().allMatch(s->s.id()<a.items().getFirst().id()));assertNull(b.nextCursor());assertThrows(Exception.class,()->history.list(from,to,"HR2","ALL",2,a.nextCursor()));assertThrows(Exception.class,()->history.list(from,to,"HR1","ON",2,a.nextCursor()));}
 @Test void equalReceiptTimesUseDescendingIdWithoutSkipping()throws Exception{for(int i=0;i<4;i++)receive(packet(i));jdbc.update("UPDATE pump_circuit_history SET received_at=? WHERE circuit_id='HR1'",Timestamp.from(base));var a=history.list(from,to,"HR1","ALL",2,null);var b=history.list(from,to,"HR1","ALL",2,a.nextCursor());var ids=new HashSet<Long>();a.items().forEach(s->ids.add(s.id()));b.items().forEach(s->ids.add(s.id()));assertEquals(4,ids.size());assertNull(b.nextCursor());}
 @Test void invalidRangesLimitsCursorAndConditionsAreRejected(){assertThrows(Exception.class,()->history.list(to,from,null,null,50,null));assertThrows(Exception.class,()->history.list(from,from.plusSeconds(32*86400),null,null,50,null));for(int n:new int[]{0,201})assertThrows(Exception.class,()->history.commands(from,to,null,n));assertThrows(Exception.class,()->history.list(from,to,"bad",null,50,null));assertThrows(Exception.class,()->history.list(from,to,null,"RUNNING",50,null));assertThrows(Exception.class,()->history.list(from,to,null,null,50,"bad"));}
 @Test void commandsKeepOriginalRouteAndAckMetadataWithBoundedResult(){var a=command("ON",route);command("RESET_LOCKOUT",route);command("ON",new PumpCircuitRoute("HR2",1,"HRZONE2",1,"IRRIGATION69","VALVE69"));var p=history.commands(from,to,"HR1",1);assertEquals(1,p.items().size());assertTrue(p.hasMore());assertEquals(route,p.items().getFirst().route());assertNull(p.items().getFirst().acknowledgedAt());assertEquals(a,history.commands(from,to,"HR1",50).items().getLast().commandId());}
 @Test void readonlyHttpDoesNotExpireCommandsRefreshStatusOrDispatch()throws Exception{receive(packet(0));command("ON",route);var before=jdbc.queryForObject("SELECT row_to_json(p)::text FROM pump_status p",String.class);mvc.perform(get("/api/v1/pump-circuit-history").param("from",from.toString()).param("to",to.toString()).param("circuitId","HR1")).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].route.circuitId").value("HR1"));mvc.perform(get("/api/v1/pump-circuit-history/commands").param("from",from.toString()).param("to",to.toString()).param("circuitId","HR1")).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].state").value("SENT"));assertEquals(before,jdbc.queryForObject("SELECT row_to_json(p)::text FROM pump_status p",String.class));}
 @Test void halfOpenRangeUsesReceiptTimeAndNotSourceTime()throws Exception{receive(packet(0));var s=page().items().getFirst();assertTrue(history.list(from,s.receivedAt(),"HR1","ALL",50,null).items().isEmpty());assertEquals(1,history.list(s.receivedAt(),to,"HR1","ALL",50,null).items().size());}
}
